SELECT  *
WHERE
  {   { ?city  rdfs:label  "Hamburg"@de }
    UNION
      { ?alias  dbprop:redirect  ?city ;
                rdfs:label       "Hamburg"@de
      }
    UNION
      { ?alias  dbprop:disambiguates  ?city ;
                rdfs:label            "Hamburg"@de
      }
    OPTIONAL
