PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?person ?wikipedia ?depiction ?comment
WHERE
  {   { ?person  rdfs:label  "Charles Lyell"@en ;
                 rdf:type    owl:Thing
      }
    UNION
      { ?altName  rdfs:label            "Charles Lyell"@en ;
                  dbpo:wikiPageRedirects  ?person
      }
    ?person  dbpo:birthDate  ?birthDate ;
             dbpo:deathDate  ?deathDate
    OPTIONAL
      { ?person  foaf:depiction  ?depiction }
    OPTIONAL
      { ?person  foaf:isPrimaryTopicOf  ?wikipedia }
    ?person  rdfs:comment  ?comment
    FILTER ( ?birthDate < "1860-06-06"^^xsd:date )
    FILTER ( ?deathDate > "1860-06-06"^^xsd:date )
    FILTER ( lang(?comment) = "en" )
  }
ORDER BY ?person
LIMIT   1", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  owl:  <http://www.w3.org/2002/07/owl#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?person ?wikipedia ?depiction ?comment
WHERE
  {   { ?person  rdfs:label  "Samuel L. Clemens"@en ;
                 rdf:type    owl:Thing
      }
    UNION
      { ?altName  rdfs:label            "Samuel L. Clemens"@en ;
                  dbpo:wikiPageRedirects  ?person
      }
    ?person  dbpo:birthDate  ?birthDate ;
             dbpo:deathDate  ?deathDate
    OPTIONAL
      { ?person  foaf:depiction  ?depiction }
    OPTIONAL
      { ?person  foaf:isPrimaryTopicOf  ?wikipedia }
    ?person  rdfs:comment  ?comment
    FILTER ( ?birthDate < "1909-12-27"^^xsd:date )
    FILTER ( ?deathDate > "1909-12-27"^^xsd:date )
    FILTER ( lang(?comment) = "en" )
  }
ORDER BY ?person
LIMIT   1", "PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  dbpr: <http://dbpedia.org/resource/>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?v
WHERE
  { VALUES ?v { dbpr:Charles_Messier dbpr:Pierre_Méchain <http://dbpedia.org/resource/Pierre_M%C3%A9chain> dbpr:École_des_Ponts_et_Chaussées <http://dbpedia.org/resource/%C3%89cole_des_Ponts_ParisTech> dbpr:Ponts_et_Chaussées <http://dbpedia.org/resource/%C3%89cole_des_ponts_ParisTech> <http://dbpedia.org/resource/%C3%89cole_des_Ponts_et_Chauss%C3%A9es> <http://dbpedia.org/resource/%C3%89cole_nationale_des_Ponts_et_Chauss%C3%A9es> dbpr:École_nationale_des_Ponts_et_Chaussées dbpr:École_des_ponts_ParisTech <http://dbpedia.org/resource/Ponts_et_Chauss%C3%A9es> dbpr:École_des_Ponts_ParisTech dbpr:Sahara dbpr:Italy dbpr:1770 dbpr:1795 dbpr:1787 dbpr:Astronomer dbpr:1744 dbpr:1780 dbpr:1804 dbpr:Comet dbpr:Surveying }
    ?v  rdf:type  foaf:Person
  }", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
