  { dbpr:Freddy_Thielemans
              rdfs:comment  ?field
  }", "PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  dbpo: <http://dbpedia.org/ontology/>

SELECT  ?title ?author
WHERE
  { ?title  rdf:type     dbpo:Book ;
            dbpo:author  ?author
  }
ORDER BY ?author", "PREFIX  dbpr: <http://dbpedia.org/resource/>
PREFIX  dbprop: <http://dbpedia.org/property/>

SELECT  ?v
WHERE
  { dbpr:Sweden  dbprop:gdpNominalYear  ?v }
LIMIT   1", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  gsp:  <http://www.opengis.net/ont/geosparql#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>
PREFIX  dbprop: <http://dbpedia.org/property/>

SELECT  *
WHERE
  {   { ?city  rdfs:label  "Dordrecht"@nl }
    UNION
      { ?alias  dbprop:redirect  ?city ;
                rdfs:label       "Dordrecht"@nl
      }
    UNION
      { ?alias  dbprop:disambiguates  ?city ;
                rdfs:label            "Dordrecht"@nl
      }
    OPTIONAL
      { ?city  dbpo:abstract  ?abstract }
    OPTIONAL
      { ?city  gsp:lat   ?latitude ;
               gsp:long  ?longitude
      }
    OPTIONAL
      { ?city  foaf:depiction  ?image }
    OPTIONAL
      { ?city  rdfs:label  ?name }
    OPTIONAL
      { ?city  foaf:homepage  ?home }
    OPTIONAL
      { ?city  dbpo:populationTotal  ?population }
    OPTIONAL
      { ?city  dbpo:thumbnail  ?thumbnail }
    FILTER langMatches(lang(?abstract), "nl")
  }"]

["PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?person ?deathDate ?dbpedia ?wikipedia ?depiction ?comment ?thumbnail
WHERE
  { ?dbpedia  rdfs:label      ?person ;
              rdf:type        dbpo:Person ;
              dbpo:deathDate  ?deathDate
    FILTER ( ?deathDate > "1930-01-01"^^xsd:date )
    OPTIONAL
      { ?dbpedia  foaf:isPrimaryTopicOf  ?wikipedia }
    OPTIONAL
      { ?dbpedia  foaf:depiction  ?depiction }
    ?dbpedia  rdfs:comment  ?comment
    FILTER ( lang(?person) = "en" )
    FILTER ( lang(?comment) = "en" )
  }
LIMIT   10", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>
PREFIX  dbprop: <http://dbpedia.org/property/>

SELECT  *
WHERE
  { ?city     rdf:type    dbpo:Place ;
              rdfs:label  "Oxnard"@sv .
    ?airport  rdf:type    dbpo:Airport
      { ?airport  dbpo:city  ?city }
    UNION
      { ?airport  dbpo:location  ?city }
    UNION
      { ?airport  dbprop:cityServed  ?city }
    UNION
      { ?airport  dbpo:city  ?city }
      { ?airport  dbprop:iata  ?iata }
    UNION
      { ?airport  dbpo:iataLocationIdentifier  ?iata }
    OPTIONAL
      { ?airport  foaf:homepage  ?airport_home }
    OPTIONAL
      { ?airport  rdfs:label  ?name }
    OPTIONAL
      { ?airport  dbprop:nativename  ?airport_name }
    FILTER ( ( ! bound(?name) ) || langMatches(lang(?name), "sv") )
  }", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  owl:  <http://www.w3.org/2002/07/owl#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?person ?wikipedia ?depiction ?comment
WHERE
  {   { ?person  rdfs:label  "Charles Lyell"@en ;
                 rdf:type    owl:Thing
      }
    UNION
      { ?altName  rdfs:label            "Charles Lyell"@en ;
                  dbpo:wikiPageRedirects  ?person
      }
    ?person  dbpo:birthDate  ?birthDate ;
             dbpo:deathDate  ?deathDate
    OPTIONAL
      { ?person  foaf:depiction  ?depiction }
    OPTIONAL
      { ?person  foaf:isPrimaryTopicOf  ?wikipedia }
    ?person  rdfs:comment  ?comment
    FILTER ( ?birthDate < "1860-06-06"^^xsd:date )
    FILTER ( ?deathDate > "1860-06-06"^^xsd:date )
    FILTER ( lang(?comment) = "en" )
  }
ORDER BY ?person
LIMIT   1", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
