SELECT  *
WHERE
  {   { ?city  rdfs:label  "Derby"@en }
    UNION
      { ?alias  dbprop:redirect  ?city ;
                rdfs:label       "Derby"@en
      }
    UNION
      { ?alias  dbprop:disambiguates  ?city ;
                rdfs:label            "Derby"@en
      }
    OPTIONAL
      { ?city  dbpo:abstract  ?abstract }
    OPTIONAL
      { ?city  gsp:lat   ?latitude ;
               gsp:long  ?longitude
      }
