PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?person ?wikipedia ?depiction ?comment
WHERE
  {   { ?person  rdfs:label  "Ernest Hemingway"@en ;
                 rdf:type    owl:Thing
      }
    UNION
      { ?altName  rdfs:label            "Ernest Hemingway"@en ;
                  dbpo:wikiPageRedirects  ?person
      }
    ?person  dbpo:birthDate  ?birthDate ;
             dbpo:deathDate  ?deathDate
    OPTIONAL
      { ?person  foaf:depiction  ?depiction }
    OPTIONAL
      { ?person  foaf:isPrimaryTopicOf  ?wikipedia }
    ?person  rdfs:comment  ?comment
    FILTER ( ?birthDate < "1920-11-20"^^xsd:date )
    FILTER ( ?deathDate > "1920-11-20"^^xsd:date )
    FILTER ( lang(?comment) = "en" )
  }
ORDER BY ?person
LIMIT   1", "PREFIX  :     <http://dbpedia.org/resource/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT  ?t
WHERE
  { :Lee_Gi-dong  rdf:type  ?t }", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
