  {   { ?person  rdfs:label  "Charles Robert Darwin"@en ;
                 rdf:type    owl:Thing
      }
    UNION
      { ?altName  rdfs:label            "Charles Robert Darwin"@en ;
                  dbpo:wikiPageRedirects  ?person
