positive_queries:
["PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  dbpr: <http://dbpedia.org/resource/>

SELECT  ?p ?date
WHERE
  { ?p  rdf:type  dbpo:Film
    OPTIONAL
      { ?p  dbpo:releaseDate  ?date }
      { ?p  dbpo:starring  dbpr:Woody_Allen }
    UNION
      { ?p  dbpo:director  dbpr:Woody_Allen }
    UNION
      { ?p  dbpo:author  dbpr:Woody_Allen }
  }
ORDER BY ?date", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  dbpr: <http://dbpedia.org/resource/>

SELECT  ?p ?date
WHERE
  { ?p  rdf:type  dbpo:Film
    OPTIONAL
      { ?p  dbpo:releaseDate  ?date }
    OPTIONAL
      { ?p  dbpo:released  ?date }
      { ?p  dbpo:starring  dbpr:Woody_Allen }
    UNION
      { ?p  dbpo:director  dbpr:Woody_Allen }
    UNION
      { ?p  dbpo:author  dbpr:Woody_Allen }
  }
ORDER BY DESC(?date)"]

