SELECT DISTINCT  ?v
WHERE
  { VALUES ?v { dbpr:René_Descartes <http://dbpedia.org/resource/Ren%C3%A9_Descartes> dbpr:Descartes dbpr:Digne-les-Bains dbpr:Pierre_Gassendi dbpr:Pierre_Gassendi dbpr:Metaphysics dbpr:Rene_Descartes dbpr:René_Descartes <http://dbpedia.org/resource/Ren%C3%A9_Descartes> dbpr:Descartes dbpr:Pierre_Gassendi dbpr:Pierre_Gassendi dbpr:First_Data dbpr:Pierre_Gassendi dbpr:Digne-les-Bains dbpr:Agglomerate dbpr:Pierre_Gassendi dbpr:Sinecure dbpr:Society_of_Jesus dbpr:Grenoble dbpr:Rene_Descartes dbpr:René_Descartes <http://dbpedia.org/resource/Ren%C3%A9_Descartes> }
    ?v  rdf:type  foaf:Person
  }", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>
PREFIX  dbprop: <http://dbpedia.org/property/>

SELECT  *
WHERE
  { ?city     rdf:type    dbpo:Place ;
              rdfs:label  "Coimbatore"@en .
    ?airport  rdf:type    dbpo:Airport
      { ?airport  dbpo:city  ?city }
    UNION
      { ?airport  dbpo:location  ?city }
    UNION
      { ?airport  dbprop:cityServed  ?city }
    UNION
      { ?airport  dbpo:city  ?city }
      { ?airport  dbprop:iata  ?iata }
    UNION
      { ?airport  dbpo:iataLocationIdentifier  ?iata }
    OPTIONAL
      { ?airport  foaf:homepage  ?airport_home }
    OPTIONAL
      { ?airport  rdfs:label  ?name }
    OPTIONAL
      { ?airport  dbprop:nativename  ?airport_name }
    FILTER ( ( ! bound(?name) ) || langMatches(lang(?name), "de") )
  }", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  owl:  <http://www.w3.org/2002/07/owl#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?person ?wikipedia ?depiction ?comment
WHERE
  {   { ?person  rdfs:label  "Ernest Hemingway"@en ;
                 rdf:type    owl:Thing
      }
    UNION
      { ?altName  rdfs:label            "Ernest Hemingway"@en ;
                  dbpo:wikiPageRedirects  ?person
      }
    ?person  dbpo:birthDate  ?birthDate ;
             dbpo:deathDate  ?deathDate
    OPTIONAL
      { ?person  foaf:depiction  ?depiction }
    OPTIONAL
      { ?person  foaf:isPrimaryTopicOf  ?wikipedia }
    ?person  rdfs:comment  ?comment
    FILTER ( ?birthDate < "1927-08-26"^^xsd:date )
    FILTER ( ?deathDate > "1927-08-26"^^xsd:date )
    FILTER ( lang(?comment) = "en" )
  }
ORDER BY ?person
LIMIT   1"]

