SELECT  ?movie ?releaseDate
WHERE
  {   { ?movie  dbpo:director     dbpr:Woody_Allen ;
                dbpo:releaseDate  ?releaseDate
      }
    UNION
      { ?movie  dbpo:writer       dbpr:Woody_Allen ;
                dbpo:releaseDate  ?releaseDate
      }
    UNION
      { ?movie  dbpo:starring     dbpr:Woody_Allen ;
                dbpo:releaseDate  ?releaseDate
      }
  }
ORDER BY ?releaseDate

