SELECT DISTINCT  ?name ?birthDate ?description ?starring
WHERE
  { ?person  dbpo:occupation  :Actor ;
             dbpo:birthPlace  :Brussels ;
             dbpo:birthDate   ?birthDate ;
             foaf:name        ?name ;
             rdfs:comment     ?description
    FILTER ( lang(?description) = "en" )
  }
ORDER BY ?name
LIMIT   5

