    OPTIONAL
      { ?person  foaf:isPrimaryTopicOf  ?wikipedia }
    ?person  rdfs:comment  ?comment
    FILTER ( ?birthDate < "1933-08-21"^^xsd:date )
    FILTER ( ?deathDate > "1933-08-21"^^xsd:date )
    FILTER ( lang(?comment) = "en" )
  }
ORDER BY ?person
LIMIT   1"]

