SELECT DISTINCT  ?title ?author
WHERE
  { ?a     rdf:type            dbpo:Book ;
           rdfs:label          ?title ;
           dbpo:numberOfPages  ?numri ;
           dbpo:abstract       ?abs ;
           dbpo:author         ?name .
    ?name  foaf:name           ?author
    FILTER ( lang(?title) = "en" )
  }
LIMIT   100

