    FILTER ( ( ( ( ( ( ( ( ( ( ?resource = dbpr:Radioisotope_thermoelectric_generator ) || ( ?resource = dbpr:Multi-Mission_Radioisotope_Thermoelectric_Generator ) ) || ( ?resource = dbpr:Plutonium ) ) || ( ?resource = dbpr:New_Horizons_2 ) ) || ( ?resource = dbpr:Plutonium-238 ) ) || ( ?resource = dbpr:Iridium ) ) || ( ?resource = dbpr:Strontium-90 ) ) || ( ?resource = dbpr:Neptune_Orbiter ) ) || ( ?resource = dbpr:GPHS-RTG ) ) || ( ?resource = dbpr:General_Purpose_Heat_Source ) )
