SELECT DISTINCT  ?v
WHERE
  { VALUES ?v { dbpr:Nobel_Prize dbpr:Louis_XVI_of_France dbpr:Louis_XV_of_France dbpr:Louis_XVII_of_France dbpr:Louis_XIV_of_France dbpr:Académie_des_Beaux-Arts dbpr:Sorbonne dbpr:University dbpr:Eiffel_Tower dbpr:September dbpr:Google dbpr:Joke dbpr:Google <http://dbpedia.org/resource/Universum_(band)> dbpr:Sergey_Brin dbpr:Google dbpr:Friday dbpr:Google dbpr:Larry_Page dbpr:Larry_Page dbpr:Silicon_Valley dbpr:Larry_Page dbpr:Google dbpr:Sergey_Brin }
    ?v  rdf:type  dbpo:Place
  }", "PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
