  {   { ?person  rdfs:label  "Howard P. Lovecraft"@en ;
                 rdf:type    owl:Thing
      }
    UNION
      { ?altName  rdfs:label            "Howard P. Lovecraft"@en ;
                  dbpo:wikiPageRedirects  ?person
      }
    ?person  dbpo:birthDate  ?birthDate ;
             dbpo:deathDate  ?deathDate
    OPTIONAL
      { ?person  foaf:depiction  ?depiction }
    OPTIONAL
      { ?person  foaf:isPrimaryTopicOf  ?wikipedia }
    ?person  rdfs:comment  ?comment
    FILTER ( ?birthDate < "1930-05-15"^^xsd:date )
    FILTER ( ?deathDate > "1930-05-15"^^xsd:date )
    FILTER ( lang(?comment) = "en" )
  }
ORDER BY ?person
