SELECT DISTINCT  ?b ?v0
WHERE
  { { ?b  rdf:type  dul:ChemicalObject }
    OPTIONAL
      { ?b  rdfs:label  ?v0 }
  }
OFFSET  30000
LIMIT   1000", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
