PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?v
WHERE
  { VALUES ?v { <http://dbpedia.org/resource/Poincar%C3%A9> dbpr:Poincaré <http://dbpedia.org/resource/Poincar%C3%A9> dbpr:Poincaré <http://dbpedia.org/resource/Poincar%C3%A9> dbpr:Poincaré <http://dbpedia.org/resource/Poincar%C3%A9> dbpr:Poincaré <http://dbpedia.org/resource/Poincar%C3%A9> dbpr:Poincaré <http://dbpedia.org/resource/Poincar%C3%A9> dbpr:Poincaré <http://dbpedia.org/resource/Poincar%C3%A9> dbpr:Poincaré <http://dbpedia.org/resource/Poincar%C3%A9> dbpr:Poincaré dbpr:University_of_Caen_Lower_Normandy dbpr:Academy_of_Sciences dbpr:Paris dbpr:Paris <http://dbpedia.org/resource/Acad%C3%A9mie_fran%C3%A7aise> dbpr:French_Academy dbpr:Académie_française dbpr:Henri_Poincaré }
    ?v  rdf:type  foaf:Person
  }", "SELECT  ?s ?p ?o
WHERE
  { ?s  ?p  ?o }
LIMIT   10", "PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?person ?deathDate ?dbpedia ?wikipedia ?depiction ?comment ?thumbnail
WHERE
  { ?dbpedia  rdfs:label      ?person ;
              rdf:type        dbpo:Person ;
              dbpo:deathDate  ?deathDate
    FILTER ( ?deathDate > "1960-01-01"^^xsd:date )
    OPTIONAL
      { ?dbpedia  foaf:isPrimaryTopicOf  ?wikipedia }
    OPTIONAL
      { ?dbpedia  foaf:depiction  ?depiction }
    ?dbpedia  rdfs:comment  ?comment
    FILTER ( lang(?person) = "en" )
    FILTER ( lang(?comment) = "en" )
  }
LIMIT   10"]

