negative_queries:
["PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  gsp:  <http://www.opengis.net/ont/geosparql#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>
PREFIX  dbprop: <http://dbpedia.org/property/>

SELECT  *
WHERE
  {   { ?city  rdfs:label  "Renchen"@en }
    UNION
      { ?alias  dbprop:redirect  ?city ;
                rdfs:label       "Renchen"@en
      }
    UNION
      { ?alias  dbprop:disambiguates  ?city ;
                rdfs:label            "Renchen"@en
      }
    OPTIONAL
      { ?city  dbpo:abstract  ?abstract }
    OPTIONAL
      { ?city  gsp:lat   ?latitude ;
               gsp:long  ?longitude
      }
    OPTIONAL
      { ?city  foaf:depiction  ?image }
    OPTIONAL
      { ?city  rdfs:label  ?name }
    OPTIONAL
      { ?city  foaf:homepage  ?home }
    OPTIONAL
      { ?city  dbpo:populationTotal  ?population }
    OPTIONAL
      { ?city  dbpo:thumbnail  ?thumbnail }
    FILTER langMatches(lang(?abstract), "sv")
  }", "PREFIX  dbpr: <http://dbpedia.org/resource/>
PREFIX  dbpo: <http://dbpedia.org/ontology/>

SELECT DISTINCT  ?thumbnail_link
WHERE
  { dbpr:BlackBerry_Tablet_OS
              dbpo:thumbnail  ?thumbnail_link
  }
LIMIT   10000", "PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?person ?birthDate ?dbpedia ?wikipedia ?depiction ?comment ?thumbnail
WHERE
  { ?dbpedia  rdfs:label      ?person ;
              rdf:type        dbpo:Person ;
              dbpo:birthDate  ?birthDate
    FILTER ( ?birthDate > "1800-01-01"^^xsd:date )
    OPTIONAL
      { ?dbpedia  foaf:isPrimaryTopicOf  ?wikipedia }
    OPTIONAL
      { ?dbpedia  foaf:depiction  ?depiction }
    ?dbpedia  rdfs:comment  ?comment
    FILTER ( lang(?person) = "en" )
    FILTER ( lang(?comment) = "en" )
  }
LIMIT   10", "PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  dbpr: <http://dbpedia.org/resource/>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?v
WHERE
  { VALUES ?v { dbpr:Early_Birds_of_Aviation dbpr:Juan_de_la_Cierva dbpr:Turbine dbpr:España dbpr:Spain <http://dbpedia.org/resource/Espa%C3%B1a> dbpr:Bomber dbpr:Typeface dbpr:Cierva_Autogiro_Company dbpr:Innovation dbpr:Pitcher <http://dbpedia.org/resource/Lift_(force)> dbpr:Juan_de_la_Cierva <http://dbpedia.org/resource/Farnborough,_Hampshire> dbpr:Autogyro dbpr:Tendency_of_the_rate_of_profit_to_fall dbpr:Year dbpr:Douglas_DC-2 <http://dbpedia.org/resource/Earth's_atmosphere> dbpr:Atmosphere_of_Earth dbpr:Autogyro dbpr:Flight dbpr:Airspeed dbpr:Dutch_language }
    ?v  rdf:type  foaf:Person
  }", "PREFIX  dct:  <http://purl.org/dc/terms/>
PREFIX  dbpr: <http://dbpedia.org/resource/>

SELECT DISTINCT  ?category
WHERE
  { <http://dbpedia.org/resource/Salve_(film)>
              dct:subject  ?category
  }"]

