SELECT DISTINCT  ?v
WHERE
  { VALUES ?v { <http://dbpedia.org/resource/Division_(military)> dbpr:Stuttgart dbpr:Academy dbpr:Theory dbpr:Emergency_Committee_of_South_Australia dbpr:University dbpr:Trinity dbpr:Temperature <http://dbpedia.org/resource/0_(number)> dbpr:Avia_Traffic_Company <http://dbpedia.org/resource/LAMP_(software_bundle)> dbpr:Matter dbpr:Football_Conference dbpr:Albert_Einstein dbpr:Raha-automaattiyhdistys dbpr:Nagasaki dbpr:University <http://dbpedia.org/resource/Knoxville,_Tennessee> dbpr:Frankfurt dbpr:Fourier_transform dbpr:July dbpr:England dbpr:Socialist_Party dbpr:Germany }
    ?v  rdf:type  foaf:Person
  }", "PREFIX  dbpo: <http://dbpedia.org/ontology/>
